            containsTOFU: true // Adiciona um novo campo se a palavra for encontrada
        });
    }
}

// Retorna os resultados
return results.length > 0 ? results : [{ message: "Nenhuma campanha foi encontrada." }];

const input = $item("0").$node["Aggregate3"].json["data"];

const transformData = (data) => {
    // Verificar se data é um array válido
    if (!Array.isArray(data)) {
        return [];
    }

    // Estrutura para armazenar dados agregados
    const campaigns = {};
    const allAds = [];

    // Processa cada item
    data.forEach(item => {
        if (!item) return;

        const campaignName = item.campaign_name || "";
        const adsetName = item.adset_name || "";
        const adName = item.ad_name || "";
        const spend = parseFloat(item.spend) || 0;

        // Busca por leads nas actions
        let leads = 0;
        if (item.actions && Array.isArray(item.actions)) {
            const leadAction = item.actions.find(action => 
                action && action.action_type === "lead"
            );
            if (leadAction) {
                leads = parseInt(leadAction.value) || 0;
            }
        }

        // Armazena CADA ocorrência do anúncio (não agregado)
        if (leads > 0) { // Só adiciona se tiver leads
            allAds.push({
                campaign_name: campaignName,
                adset_name: adsetName,
                ad_name: adName,
                spend: spend,
                leads: leads,
                cpl: spend / leads
            });
        }

        // Inicializa estrutura da campanha se não existir
        if (!campaigns[campaignName]) {
            campaigns[campaignName] = {
                adsets: {},
                totalSpend: 0,
                totalLeads: 0
            };
        }

        // Inicializa conjunto de anúncios se não existir
        if (!campaigns[campaignName].adsets[adsetName]) {
            campaigns[campaignName].adsets[adsetName] = {
                spend: 0,
                leads: 0
            };
        }

        // Acumula valores
        campaigns[campaignName].adsets[adsetName].spend += spend;
        campaigns[campaignName].adsets[adsetName].leads += leads;
        campaigns[campaignName].totalSpend += spend;
        campaigns[campaignName].totalLeads += leads;
    });

    // Gera array de resultados formatados
    const results = [];
    let campaignIndex = 1;

    Object.keys(campaigns).forEach(campaignName => {
        const campaign = campaigns[campaignName];

        // Adiciona header da campanha
        results.push({
            tipo: "header_campanha",
            texto: `Campanha ${campaignIndex}: ${campaignName}`
        });

        // Adiciona conjuntos de anúncios
        let adsetIndex = 1;
        Object.keys(campaign.adsets).forEach(adsetName => {
            const adset = campaign.adsets[adsetName];
            const cpl = adset.leads > 0 ? (adset.spend / adset.leads) : 0;

            results.push({
                tipo: "conjunto_anuncio",
                numero: adsetIndex,
                nome: adsetName,
                investimento: adset.spend,
                investimento_formatado: `R$ ${adset.spend.toFixed(2).replace('.', ',')}`,
                leads: adset.leads,
                custo_por_lead: cpl,
                custo_por_lead_formatado: `R$ ${cpl.toFixed(2).replace('.', ',')}`
            });

            adsetIndex++;
        });

        // Adiciona totais
        const avgCpl = campaign.totalLeads > 0 ? (campaign.totalSpend / campaign.totalLeads) : 0;
        results.push({
            tipo: "total",
            investimento_total: campaign.totalSpend,
            investimento_formatado: `R$ ${campaign.totalSpend.toFixed(2).replace('.', ',')}`,
            leads_total: campaign.totalLeads,
            custo_medio_por_lead: avgCpl,
            custo_medio_formatado: `R$ ${avgCpl.toFixed(2).replace('.', ',')}`
        });

        // Encontra melhor criativo (menor CPL entre os que têm leads)
        let bestAd = null;
        allAds.forEach(ad => {
            if (ad.campaign_name === campaignName) {
                if (!bestAd || ad.cpl < bestAd.cpl) {
                    bestAd = ad;
                }
            }
        });

        // Adiciona melhor criativo
        if (bestAd) {
            results.push({
                tipo: "melhor_criativo",
                nome: bestAd.ad_name,
                conjunto_anuncio: bestAd.adset_name,
                leads: bestAd.leads,
                custo_por_lead: bestAd.cpl,
                custo_por_lead_formatado: `R$ ${bestAd.cpl.toFixed(2).replace('.', ',')}`
            });
        } else {
            results.push({
                tipo: "melhor_criativo",
                mensagem: "Nenhum criativo gerou leads"
            });
        }

        campaignIndex++;
    });

    return results;
};

